import{_ as a,o as i,c as l,a2 as t}from"./chunks/framework.ClgMjOt7.js";const h=JSON.parse('{"title":"ログイン","description":"Webログインとリフレッシュトークンを使ったログイン方法。","frontmatter":{"title":"ログイン","description":"Webログインとリフレッシュトークンを使ったログイン方法。"},"headers":[],"relativePath":"guide/login.md","filePath":"guide/login.md","lastUpdated":1789107345000}'),r={name:"guide/login.md"};function o(s,e,n,d,c,p){return i(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="ログイン" tabindex="-1">ログイン <a class="header-anchor" href="#ログイン" aria-label="Permalink to &quot;ログイン&quot;">​</a></h1><p>Palleriaでは、Webログインとリフレッシュトークンの2つの方法を利用できます。</p><h2 id="webログイン" tabindex="-1">Webログイン <a class="header-anchor" href="#webログイン" aria-label="Permalink to &quot;Webログイン&quot;">​</a></h2><p>多くの方にはWebログインをおすすめします。アプリ内に表示されるPixivのログインページで認証します。</p><ol><li>Palleriaを起動して「Webログイン」を選びます。</li><li>表示されたPixivのページでログインします。</li><li>認証が完了するとPalleriaに戻ります。</li></ol><p>ログインページや二段階認証の表示はPixiv側の仕様により変わることがあります。</p><h2 id="リフレッシュトークン" tabindex="-1">リフレッシュトークン <a class="header-anchor" href="#リフレッシュトークン" aria-label="Permalink to &quot;リフレッシュトークン&quot;">​</a></h2><p>すでに有効なPixivリフレッシュトークンを持っている場合は、トークンを入力して直接ログインできます。</p><div class="danger custom-block"><p class="custom-block-title">トークンを共有しないでください</p><p>リフレッシュトークンはパスワードと同様に扱ってください。スクリーンショット、Issue、ログ、チャットなどに貼り付けないでください。トークンを知った第三者がアカウントへアクセスできる可能性があります。</p></div><h2 id="ログインできないとき" tabindex="-1">ログインできないとき <a class="header-anchor" href="#ログインできないとき" aria-label="Permalink to &quot;ログインできないとき&quot;">​</a></h2><ul><li>端末の日時が自動設定になっているか確認する</li><li>ネットワークを切り替えて再試行する</li><li>VPN、広告ブロッカー、独自DNSを一時的に無効にする</li><li>Palleriaを最新版に更新する</li><li>Pixiv公式サイトでアカウントにログインできるか確認する</li></ul><p>解決しない場合は、トークンや個人情報を含めずに<a href="https://github.com/yunfie-twitter/Palleria/issues" target="_blank" rel="noreferrer">GitHub Issues</a>へ状況を報告してください。</p>',12)])])}const b=a(r,[["render",o]]);export{h as __pageData,b as default};
